def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of positive integer sequences with the prescribed reduced ratios.

    For each prime, adjacent exponents differ by its exponent in a[i].
    Normalize the exponent walk to have minimum zero, enforcing gcd(S) = 1.
    Prime exponent walks are independent, so their weighted sums multiply.
    """
    mod = 998244353
    exponents = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                count = 0
                while value % p == 0:
                    value //= p
                    count += 1
                if p not in exponents:
                    exponents[p] = [0] * (n - 1)
                exponents[p][i] = count
            p += 1
        if value > 1:
            if value not in exponents:
                exponents[value] = [0] * (n - 1)
            exponents[value][i] = 1

    answer = 1
    for p, steps in exponents.items():
        total = sum(steps)
        powers = [1] * (total + 1)
        for j in range(1, total + 1):
            powers[j] = powers[j - 1] * p % mod

        # dp[h] sums scores of normalized prefixes whose last exponent is h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue
            nxt = [0] * (len(dp) + step)
            # If the downward step crosses zero, all i previous exponents
            # increase by step-h when we normalize the extended prefix.
            shift_base = pow(p, i, mod)
            shifts = [1] * (step + 1)
            for j in range(1, step + 1):
                shifts[j] = shifts[j - 1] * shift_base % mod
            for h, weight in enumerate(dp):
                up = h + step
                nxt[up] = (nxt[up] + weight * powers[up]) % mod
                if h >= step:
                    down = h - step
                    nxt[down] = (nxt[down] + weight * powers[down]) % mod
                else:
                    nxt[0] = (nxt[0] + weight * shifts[step - h]) % mod
            dp = nxt
        answer = answer * (sum(dp) % mod) % mod
    return answer

from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] with digit sums in [min_sum, max_sum].

    Return the count modulo 10^9 + 7. Bounds are numeric strings representing
    integers from 1 through 10^22, and 1 <= min_sum <= max_sum <= 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        cap = min(max_sum, 9 * len(digits))

        @lru_cache(None)
        def dp(position: int, digit_sum: int, tight: bool) -> int:
            if digit_sum > cap:
                return 0
            if digit_sum + 9 * (len(digits) - position) < min_sum:
                return 0
            if position == len(digits):
                return int(min_sum <= digit_sum <= cap)

            limit = digits[position] if tight else 9
            total = 0
            for digit in range(min(limit, cap - digit_sum) + 1):
                total += dp(position + 1, digit_sum + digit,
                            tight and digit == limit)
            return total % modulus

        return dp(0, 0, True)

    # Subtract the count through the lower bound, then restore that bound
    # itself when it satisfies the requested digit-sum interval.
    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

